<template><section><header class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><h1 class="page-title mb-1">Biên tập video tương tác</h1><p class="page-subtitle mb-0">Bài 1: Vue.js là gì? • Thời lượng 10:00</p></div><div class="d-flex gap-2"><button class="btn btn-light"><i class="bi bi-eye"></i> Xem như học viên</button><button class="btn btn-brand"><i class="bi bi-check-lg"></i> Lưu thay đổi</button></div></header><div class="editor-grid"><div class="app-card overflow-hidden"><div class="video"><span class="video-label">VUE 3 • BÀI 1</span><button class="play" @click="playing=!playing"><i :class="['bi',playing?'bi-pause-fill':'bi-play-fill']"></i></button><div class="controls"><button @click="playing=!playing"><i :class="['bi',playing?'bi-pause':'bi-play']"></i></button><span>{{ formatTime(currentTime) }} / 10:00</span><input v-model.number="currentTime" type="range" min="0" max="600"><i class="bi bi-volume-up"></i><i class="bi bi-fullscreen"></i></div></div><div class="p-3 d-flex flex-wrap justify-content-between align-items-center gap-2"><div><small class="text-secondary">Vị trí hiện tại</small><strong class="d-block fs-4">{{ formatTime(currentTime) }}</strong></div><button class="btn btn-blue" @click="addAtCurrent"><i class="bi bi-plus-lg"></i> Thêm câu hỏi tại {{ formatTime(currentTime) }}</button></div></div><aside class="app-card"><div class="p-3"><h2 class="h5 fw-bold mb-1">Câu hỏi tương tác</h2><small class="text-secondary">{{ items.length }} mốc trong video</small></div><div class="interaction" v-for="(item,index) in items" :key="item.id" :class="{selected:selected?.id===item.id}" @click="selected=item"><span>{{ formatTime(item.time) }}</span><div><strong>{{ item.label }}</strong><small>{{ item.type }} • {{ item.score || 10 }} điểm</small></div><button class="btn btn-light btn-sm"><i class="bi bi-grip-vertical"></i></button></div></aside></div><div class="app-card p-4 mt-4"><div class="d-flex justify-content-between mb-2"><h2 class="h5 fw-bold">Dòng thời gian tương tác</h2><small>00:00 — 10:00</small></div><div class="editor-timeline"><div class="track-progress" :style="{width:(currentTime/600*100)+'%'}"></div><button v-for="item in items" :key="item.id" class="timeline-point" :style="{left:(item.time/600*100)+'%'}" @click="currentTime=item.time;selected=item"><i class="bi bi-patch-question-fill"></i><span>{{ formatTime(item.time) }}</span></button></div></div><div v-if="selected" class="app-card p-4 mt-4"><h2 class="h5 fw-bold">Thiết lập tương tác</h2><div class="row g-3"><div class="col-md-3"><label class="form-label">Thời điểm</label><input v-model.number="selected.time" type="number" class="form-control"></div><div class="col-md-6"><label class="form-label">Câu hỏi</label><input v-model="selected.label" class="form-control"></div><div class="col-md-3"><label class="form-label">Điểm</label><input v-model="selected.score" type="number" class="form-control"></div><div class="col-md-4 form-check ms-2"><input id="required" v-model="selected.required" class="form-check-input" type="checkbox"><label for="required">Bắt buộc trả lời</label></div><div class="col-md-4 form-check"><input id="pause" v-model="selected.pauseVideo" class="form-check-input" type="checkbox"><label for="pause">Tạm dừng video</label></div></div></div></section></template>
<script setup>import { ref } from 'vue';import { interactions } from '../../data/demo';const items=ref(structuredClone(interactions)),currentTime=ref(65),playing=ref(false),selected=ref(items.value[1]);function formatTime(t){return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`}function addAtCurrent(){const item={id:Date.now(),time:currentTime.value,label:'Câu hỏi mới',type:'SINGLE_CHOICE',score:10,required:true,pauseVideo:true};items.value.push(item);items.value.sort((a,b)=>a.time-b.time);selected.value=item}</script>
<style scoped>.editor-grid{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:1rem}.video{height:420px;background:radial-gradient(circle at 70% 20%,#266995,#0a2a43 55%,#061923);position:relative;display:grid;place-items:center;color:white}.video-label{position:absolute;left:24px;top:22px;background:#07875a;border-radius:8px;padding:.45rem .7rem;font-weight:850}.play{width:70px;height:70px;border-radius:50%;border:0;background:#ffff1a;font-size:1.8rem}.controls{position:absolute;left:0;right:0;bottom:0;display:flex;align-items:center;gap:.7rem;padding:.8rem;background:rgba(0,0,0,.45)}.controls button{border:0;background:transparent;color:white}.controls input{flex:1;accent-color:#ffff1a}.interaction{display:grid;grid-template-columns:52px 1fr auto;gap:.65rem;align-items:center;padding:.85rem 1rem;border-top:1px solid #e7ecea;cursor:pointer}.interaction:hover,.interaction.selected{background:#e9f6f1}.interaction>span{color:#005099;font-weight:850}.interaction>div{display:grid}.interaction small{color:#7c8b86;font-size:.72rem}.editor-timeline{height:7px;border-radius:99px;background:#e4ebe8;position:relative;margin:3rem 1rem}.track-progress{height:100%;background:#07875a;border-radius:99px}.timeline-point{position:absolute;top:50%;transform:translate(-50%,-50%);border:0;background:transparent;color:#cd1b1b;font-size:1.25rem}.timeline-point span{position:absolute;top:24px;left:50%;transform:translateX(-50%);font-size:.68rem;color:#52645e;white-space:nowrap}@media(max-width:1000px){.editor-grid{grid-template-columns:1fr}.video{height:48vw;min-height:300px}}</style>
